class Emitter {
  listeners = [];
  on(listener) {
    this.listeners.push(listener);
  }
  emit() {
    for (const listener of [...this.listeners]) listener();
  }
}

const bus = new Emitter();
bus.on(() => {
  console.log("A");
  bus.on(() => console.log("C"));
});
bus.on(() => console.log("B"));

bus.emit();
bus.emit();
